find:
#q, #k, #h { padding: 1em 1.6em; border-radius: .7em; background: #03131cb3; }

/* detail level: three buttons in a row, the current one lit */
#q { display: flex; align-items: center; gap: .4em; padding: .4em; }
#q span { flex: 1; color: #7ff3ff; }
#q button { flex: 1.2; padding: .7em 0; background: none; box-shadow: none; color: #e8fbff; }
#q button:hover { background: #7ff3ff33; }
#q .on { background: linear-gradient(#9ff6ff, #19c3d6); box-shadow: inset 0 -.2em #0003; color: #03222d; pointer-events: none; }

replace:
#q, #n, #k, #h { padding: 1em 1.6em; border-radius: .7em; background: #03131cb3; }

/* detail level and day / night: buttons in a row, the current one lit */
#q, #n { display: flex; align-items: center; gap: .4em; padding: .4em; }
#q span, #n span { flex: 1; color: #7ff3ff; }
#q button, #n button { flex: 1.2; padding: .7em 0; background: none; box-shadow: none; color: #e8fbff; }
#q button:hover, #n button:hover { background: #7ff3ff33; }
#q .on, #n .on { background: linear-gradient(#9ff6ff, #19c3d6); box-shadow: inset 0 -.2em #0003; color: #03222d; pointer-events: none; }
